-- Code generated by togo. PostgreSQL schema fragment (converted from togo's SQLite-only template) — hand-editable; desired state for atlas migrate diff.
CREATE TABLE scripts (
    id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
    team_id text NOT NULL,
    name text NOT NULL,
    description text NOT NULL DEFAULT '',
    body text NOT NULL,
    default_args jsonb NOT NULL DEFAULT '{}',
    env_names jsonb NOT NULL DEFAULT '[]',
    run_as text NOT NULL DEFAULT 'root',
    timeout_seconds bigint NOT NULL DEFAULT 600,
    created_by text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Hosbah (MH-576 D5): team-scoped script library ("recipes" in the roadmap doc, but that name is
-- taken by the app catalogue in catalog/ and internal/agentproto/recipes.go). body is the shell
-- script text run with bash on a target server (internal/agent script.run); default_args is a JSON
-- object of ARG_NAME -> default string value, offered (never forced) when a run is started.
-- env_names is a JSON array of the environment variable names the script expects — never values;
-- values are supplied per run (script_runs.params) and, when marked secret, sealed to the target
-- agent's key exactly like a deploy's env (internal/deploy envBox), so operations.params never
-- holds plaintext. run_as is "root" or "app" (docs: a script always runs as root on the host today;
-- the column exists so a future non-root runner needs no migration). timeout_seconds is capped at
-- 3600 by both the API and the agent (agentproto.MaxScriptTimeoutSeconds).
ALTER TABLE scripts ADD CONSTRAINT scripts_run_as_check CHECK (run_as IN ('root', 'app'));
ALTER TABLE scripts ADD CONSTRAINT scripts_timeout_check CHECK (timeout_seconds BETWEEN 1 AND 3600);
ALTER TABLE scripts ADD CONSTRAINT scripts_name_check CHECK (length(name) BETWEEN 1 AND 128);
ALTER TABLE scripts ADD CONSTRAINT scripts_team_id_name_key UNIQUE (team_id, name);
CREATE INDEX scripts_team_idx ON scripts (team_id);
